import { useEffect, useState } from 'react'

export interface Slide {
  src: string
  small: string
  width: number
  height: number
  alt: string
}

export type ProjectImages = Record<string, Slide[]>

let cache: Promise<ProjectImages> | null = null

// Generated by tools/capture; one fetch shared by every component.
function load(): Promise<ProjectImages> {
  cache ??= fetch(`${import.meta.env.BASE_URL}projects/manifest.json`)
    .then((r) => (r.ok ? (r.json() as Promise<ProjectImages>) : {}))
    .catch(() => ({}))
  return cache
}

export function useProjectImages(): ProjectImages {
  const [images, setImages] = useState<ProjectImages>({})
  useEffect(() => {
    let alive = true
    load().then((m) => alive && setImages(m))
    return () => { alive = false }
  }, [])
  return images
}
